import re
def nums(s):
 if not s:return None
 o=[]
 for z in s.split(','):
  if not re.fullmatch(r'0|-?[1-9][0-9]*',z):return None
  x=int(z)
  if x < -1000 or x > 1000:return None
  o.append(x)
 return o
def join(a):return ','.join(map(str,a))
def alternating_ends(s: str) -> str | None:
 a=nums(s)
 if a is None:return None
 o=[];i=0;j=len(a)-1
 while i<=j:
  o.append(a[i]);i+=1
  if i<=j:o.append(a[j]);j-=1
 return join(o)
